/// The colour set of one palette colour on its own (`FLATS` in the script); a colour not
/// listed there panics: add it to `FLATS` and run the script again.
pub(crate) fn flat(index: u8) -> usize {
    match index {
        0 => FLAT_0,
        6 => FLAT_6,
        39 => FLAT_39,
        43 => FLAT_43,
        98 => FLAT_98,
        166 => FLAT_166,
        50 => FLAT_50,
        79 => FLAT_79,
        123 => FLAT_123,
        124 => FLAT_124,
        125 => FLAT_125,
        127 => FLAT_127,
        172 => FLAT_172,
        179 => FLAT_179,
        201 => FLAT_201,
        211 => FLAT_211,
        216 => FLAT_216,
        218 => FLAT_218,
        221 => FLAT_221,
        222 => FLAT_222,
        other => panic!("{other}"),
    }
}
